CREATE TABLE IF NOT EXISTS ai_platform.ai_coding_ci_bindings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workstream_id UUID NOT NULL REFERENCES ai_platform.ai_coding_workstreams(id) ON DELETE CASCADE,repository TEXT NOT NULL,pull_request_number TEXT NOT NULL,head_sha TEXT NOT NULL,required_checks_json JSONB NOT NULL DEFAULT '[]'::jsonb,state TEXT NOT NULL DEFAULT 'WAITING',last_checkpoint_json JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT ai_coding_ci_bindings_state_check CHECK(state IN('WAITING','GREEN','FAILED','STALE')));CREATE UNIQUE INDEX IF NOT EXISTS ai_coding_ci_bindings_workstream_uidx ON ai_platform.ai_coding_ci_bindings(workstream_id);CREATE INDEX IF NOT EXISTS ai_coding_ci_bindings_repo_sha_idx ON ai_platform.ai_coding_ci_bindings(repository,head_sha);